const validationErrors = [];
const chapterIsObject = $json.chapter !== null
  && typeof $json.chapter === 'object'
  && !Array.isArray($json.chapter);
const chapter = chapterIsObject ? $json.chapter : {};

if ($json.schema_version !== '1.0') {
  validationErrors.push('Invalid schema_version: expected 1.0.');
}
if ($json.route !== 'chapter.metadata.created') {
  validationErrors.push('Invalid route: expected chapter.metadata.created.');
}
if ($json.status !== 'ready') {
  validationErrors.push('Invalid status: expected ready.');
}
if (!chapterIsObject) {
  validationErrors.push('Invalid chapter: expected an object.');
}
if (typeof chapter.chapter_uuid !== 'string' || !chapter.chapter_uuid.trim()) {
  validationErrors.push('chapter.chapter_uuid is required.');
}
if (typeof chapter.workspace_uuid !== 'string' || !chapter.workspace_uuid.trim()) {
  validationErrors.push('chapter.workspace_uuid is required.');
}
if (typeof chapter.novel_uuid !== 'string' || !chapter.novel_uuid.trim()) {
  validationErrors.push('chapter.novel_uuid is required.');
}
if (!Number.isInteger(chapter.chapter_number) || chapter.chapter_number < 1) {
  validationErrors.push('chapter.chapter_number must be a positive integer.');
}
if (typeof chapter.chapter_filename !== 'string' || !chapter.chapter_filename.trim()) {
  validationErrors.push('chapter.chapter_filename is required.');
} else if (Number.isInteger(chapter.chapter_number) && chapter.chapter_number > 0) {
  const expectedFilename = `${String(chapter.chapter_number).padStart(4, '0')}.md`;
  if (chapter.chapter_filename !== expectedFilename) {
    validationErrors.push(`chapter.chapter_filename must equal ${expectedFilename}.`);
  }
}

return [{
  json: {
    ...$json,
    status: validationErrors.length === 0 ? 'ready' : 'error',
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors,
  },
}];

if ($json.is_valid !== true) {
  return [{ json: { ...$json } }];
}

const paddedNumber = String($json.chapter_number).padStart(4, '0');

return [{
  json: {
    ...$json,
    chapter_directory: `02_Chapters/${paddedNumber}`,
    draft_file: `${paddedNumber}.md`,
    notes_file: 'notes.md',
    assets_directory: 'assets',
    images_directory: 'images',
    exports_directory: 'exports',
    logs_directory: 'logs',
    metadata_file: 'chapter.json',
    workspace_version: '1.0',
  },
}];

const baseOutput = {
  schema_version: '1.0',
  workflow_version: '1.0',
  route: 'chapter.workspace.created',
  target: 'WF-004-P04',
};

if ($json.is_valid !== true) {
  return [{
    json: {
      ...baseOutput,
      status: 'error',
      is_valid: false,
      validation_errors: $json.validation_errors ?? [],
      workspace: null,
    },
  }];
}

return [{
  json: {
    ...baseOutput,
    status: 'ready',
    is_valid: true,
    validation_errors: [],
    workspace: {
      chapter_uuid: $json.chapter_uuid,
      workspace_uuid: $json.workspace_uuid,
      novel_uuid: $json.novel_uuid,
      chapter_number: $json.chapter_number,
      chapter_title: $json.chapter_title,
      chapter_directory: $json.chapter_directory,
      draft_file: $json.draft_file,
      notes_file: $json.notes_file,
      assets_directory: $json.assets_directory,
      images_directory: $json.images_directory,
      exports_directory: $json.exports_directory,
      logs_directory: $json.logs_directory,
      metadata_file: $json.metadata_file,
      workspace_version: $json.workspace_version,
    },
  },
}];
